mapper.select:
SELECT id, order_no, merchant_id, amount, channel, channel_trade_no, product_type, status, created_at, updated_at
FROM payment_order
WHERE order_no = #{orderNo}

SELECT id, order_no, merchant_id, amount, channel, channel_trade_no, product_type, status, created_at, updated_at
FROM payment_order
WHERE channel = #{channel}
  AND status = 'SUCCESS'
  AND channel_trade_no IS NOT NULL
  AND updated_at >= #{start}
  AND updated_at < #{end}
